using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public sealed class DiscountAcceptanceTests
{
    private readonly CalculateLoyaltyDiscount _useCase = new();

    [Fact]
    // Bronze customer pricing a 10000-cent basket is charged 9500 cents
    public void S1_BronzeCustomerPricingA10000CentBasketIsCharged9500Cents()
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }

    [Fact]
    // Silver customer pricing a 10000-cent basket is charged 9000 cents
    public void S2_SilverCustomerPricingA10000CentBasketIsCharged9000Cents()
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver));

        Assert.Equal(9000, quote.TotalCents);
    }

    [Fact]
    // Gold customer pricing a 10000-cent basket is charged 8500 cents
    public void S3_GoldCustomerPricingA10000CentBasketIsCharged8500Cents()
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Gold));

        Assert.Equal(8500, quote.TotalCents);
    }
}

